# Stand-in for a first-party SQL compiler override (not a generated file).
from other.module import SQLDeleteCompiler as BaseSQLDeleteCompiler
from other.module import SQLUpdateCompiler as BaseSQLUpdateCompiler

__all__ = ["SQLDeleteCompiler", "SQLUpdateCompiler"]


class SQLDeleteCompiler(BaseSQLDeleteCompiler):
    def as_sql(self):
        # Prefer the non-standard DELETE FROM syntax over the SQL generated by
        # the default implementation when multiple tables are involved.
        return super().as_sql()


class SQLUpdateCompiler(BaseSQLUpdateCompiler):
    def as_sql(self):
        return super().as_sql()
